def sword_story():
    root = Path(__file__).resolve().parents[1]
    runes = root / 'assets/sword/runes'
    runes.mkdir(parents=True, exist_ok=True)
    articles, nav = [], []
    project_ids = ['integraciones-mcp', 'patientar', 'vision-dji', '', 'biomodelos', 'android-nfc', 'integraciones-mcp', 'sistema-unli', 'videojuegos']
    for i, (area, title, text, stack, cta, link, drawing) in enumerate(CHAPTERS, 1):
        if project_ids[i-1]:
            link += '#' + project_ids[i-1]
        svg = f'<svg xmlns="http://www.w3.org/2000/svg" width="256" height="272" viewBox="0 0 64 68" fill="none" stroke="#8eeeff" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="{drawing}"/></svg>'
        (runes / f'rune-{i}.svg').write_text(svg, encoding='utf-8')
        nav.append(f'<a href="#tecnologia-{i}" aria-label="{escape(area)}" title="{escape(area)}"><span>{i:02}</span></a>')
        articles.append(f'''<section class="journey-chapter" id="tecnologia-{i}" data-chapter="{i}" aria-labelledby="chapter-title-{i}"><div class="chapter-copy"><div class="chapter-symbol" aria-hidden="true">{svg}</div><p class="eyebrow">{i:02} / {area}</p><h2 id="chapter-title-{i}">{title}</h2><p class="chapter-description">{text}</p><p class="chapter-stack">{stack}</p><a class="text-link" href="{link}">{cta} <span aria-hidden="true">↗</span></a></div></section>''')
    articles.append('''<section class="journey-chapter journey-outro" data-chapter="10" aria-labelledby="journey-end"><div class="chapter-copy"><p class="eyebrow">Del código al mundo real</p><h2 id="journey-end">Tu próxima idea<br>empieza aquí.</h2><p class="chapter-description">Nueve formas de explorar la tecnología. Una misma intención: construir experiencias que las personas puedan usar.</p><div class="actions"><a class="button" href="./contacto/">Conversemos ↗</a><a class="text-link" href="./proyectos/">Explorar proyectos →</a></div></div></section>''')
    return f'''<div class="sword-journey" id="recorrido"><div class="sword-stage" aria-hidden="true"><div class="stage-grid"></div><div class="stage-orbit"></div><img class="sword-poster" src="./assets/sword/reference.png" alt="" fetchpriority="high"><canvas id="sword-canvas"></canvas><span class="stage-label">NIAR / ESPADA DE NUEVE RUNAS</span></div><div class="journey-content container"><section class="journey-intro" data-chapter="0" aria-labelledby="hero-title"><div class="intro-copy"><p class="eyebrow"><span class="dot"></span> Nicolás Araya · Ingeniero Civil Informático</p><h1 id="hero-title">Ideas que<br>cobran <span>vida.</span></h1><p class="intro-description">Software, inteligencia artificial y experiencias que conectan el mundo digital con el físico.</p><div class="actions"><a class="button" href="#tecnologia-1">Explorar tecnologías <span aria-hidden="true">↓</span></a><a class="text-link" href="./proyectos/">Ver proyectos ↗</a></div><p class="scroll-cue"><span aria-hidden="true">↓</span> Desplázate para recorrer la espada</p></div><div class="intro-edition"><span>01 — 09</span><span>Nueve símbolos.<br>Un universo de posibilidades.</span></div></section>{''.join(articles)}</div><nav class="journey-nav" aria-label="Tecnologías del recorrido"><a href="#recorrido" aria-label="Inicio del recorrido" title="Inicio"><span>◇</span></a>{''.join(nav)}</nav><div class="journey-toolbar"><span class="journey-status" role="status">Preparando la espada…</span><button class="aura-toggle" type="button" aria-pressed="false">Pausar aura</button><button class="lite-toggle" type="button" aria-pressed="false">Vista ligera</button><a href="#biografia">Saltar recorrido ↓</a></div><div class="journey-progress" aria-hidden="true"><span></span></div></div>'''
